import React from "react";

function Button({
  children,
  type = "button",
  variant = "primary",
  size = "md",
  disabled = false,
  onClick,
  icon: Icon,
  className = "",
}) {
  const baseStyles = "relative inline-flex items-center justify-center font-semibold transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-60 disabled:cursor-not-allowed select-none rounded-xl";

  const variants = {
    primary: "bg-gradient-to-r from-orange-700 via-emerald-800 to-orange-600 text-white hover:opacity-95 hover:shadow-lg hover:shadow-orange-500/25 active:scale-[0.98] focus:ring-orange-600 border border-orange-500/20",
    secondary: "bg-[#0D2F24] text-white hover:bg-slate-800 hover:shadow-md active:scale-[0.98] focus:ring-slate-800",
    outline: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50 hover:border-orange-300 hover:text-orange-700 active:scale-[0.98] focus:ring-orange-500 shadow-xs",
    danger: "bg-gradient-to-r from-red-600 to-rose-600 text-white hover:opacity-95 hover:shadow-md hover:shadow-red-500/20 active:scale-[0.98] focus:ring-red-500",
    ghost: "bg-transparent text-slate-600 hover:bg-orange-50 hover:text-orange-700 active:scale-[0.98] focus:ring-orange-500",
  };

  const sizes = {
    sm: "px-3 py-1.5 text-xs gap-1.5",
    md: "px-5 py-2.5 text-sm gap-2",
    lg: "px-6 py-3.5 text-base gap-2.5",
  };

  return (
    <button
      type={type}
      onClick={onClick}
      disabled={disabled}
      className={`${baseStyles} ${variants[variant] || variants.primary} ${sizes[size] || sizes.md} ${className}`}
    >
      {Icon && <Icon className="text-current text-base" />}
      <span>{children}</span>
    </button>
  );
}

export default Button;

import React from "react";

function Card({ children, className = "", hover = true, padding = "p-6" }) {
  return (
    <div
      className={`bg-white rounded-2xl border border-slate-200/80 shadow-sm ${hover ? "hover:shadow-md hover:border-orange-200 transition-all duration-300" : ""
        } ${padding} ${className}`}
    >
      {children}
    </div>
  );
}

export default Card;

import React from "react";

function EduSphereLogo({ size = "md", showText = true, showSubtitle = false, className = "", light = false }) {
  const sizeMap = {
    sm: { icon: "w-7 h-7", text: "text-lg", sub: "text-[9px]" },
    md: { icon: "w-9 h-9", text: "text-xl", sub: "text-[10px]" },
    lg: { icon: "w-12 h-12", text: "text-2xl", sub: "text-[11px]" },
    xl: { icon: "w-16 h-16", text: "text-3xl", sub: "text-sm" },
  };

  const { icon, text, sub } = sizeMap[size] || sizeMap.md;

  return (
    <div className={`flex items-center gap-2 select-none ${className}`}>
      {/* Exact Leaf Logo SVG matching reference design */}
      <svg className={icon} viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M20 36 C10 36 4 28 4 16 C4 6 12 12 20 18 Z" fill="#1D824C" />
        <path d="M20 36 C30 36 36 28 36 16 C36 6 28 12 20 18 Z" fill="#D9531E" />
        <path d="M20 16 L23 4 L20 10 L17 4 Z" fill="#F6E05E" />
      </svg>

      {showText && (
        <div className="flex flex-col">
          <div className={`font-extrabold tracking-tight ${text} flex items-center font-sans leading-none`}>
            <span className={light ? "text-white" : "text-[#0D2F24]"}>Edu</span>
            <span className="text-[#D9531E]">Sphere</span>
          </div>
          {showSubtitle && (
            <span className={`font-bold tracking-widest uppercase mt-0.5 ${sub} ${light ? "text-white/70" : "text-[#65776F]"}`}>
              AI-Powered Coaching Platform
            </span>
          )}
        </div>
      )}
    </div>
  );
}

export default EduSphereLogo;

import React, { useState } from "react";
import { UploadCloud, FileCheck } from "lucide-react";

function FileUpload({
  label,
  register,
  error,
  accept = ".pdf,.jpg,.jpeg,.png",
  className = "",
  helperText = "PDF, JPG, PNG up to 10MB",
}) {
  const [selectedFileName, setSelectedFileName] = useState(null);

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files[0]) {
      setSelectedFileName(e.target.files[0].name);
    }
  };

  const registerProps = register || {};
  const { onChange, ...restRegister } = registerProps;

  return (
    <div className={`mb-4 ${className}`}>
      {label && (
        <label className="block mb-1.5 text-xs font-semibold uppercase tracking-wider text-slate-600 font-sans">
          {label}
        </label>
      )}

      <div className="relative">
        <label
          className={`flex flex-col items-center justify-center p-4 border-2 border-dashed rounded-xl cursor-pointer transition-all duration-200 ${
            error
              ? "border-red-400 bg-red-50/20"
              : selectedFileName
              ? "border-orange-500 bg-orange-50/30"
              : "border-slate-300 bg-slate-50/50 hover:bg-orange-50/20 hover:border-orange-400"
          }`}
        >
          <div className="flex items-center gap-3 text-slate-600">
            {selectedFileName ? (
              <FileCheck className="w-6 h-6 text-orange-600" />
            ) : (
              <UploadCloud className="w-6 h-6 text-slate-400" />
            )}
            <div className="text-left">
              <p className="text-xs font-semibold text-slate-700">
                {selectedFileName || "Click to upload document"}
              </p>
              <p className="text-[11px] text-slate-400">{helperText}</p>
            </div>
          </div>

          <input
            type="file"
            accept={accept}
            onChange={(e) => {
              handleFileChange(e);
              if (onChange) onChange(e);
            }}
            {...restRegister}
            className="hidden"
          />
        </label>
      </div>

      {error && (
        <p className="text-red-500 text-xs font-medium mt-1.5 flex items-center gap-1">
          <span>•</span> {error.message}
        </p>
      )}
    </div>
  );
}

export default FileUpload;

import React from "react";

function Input({
  label,
  type = "text",
  placeholder,
  register,
  error,
  icon: Icon,
  className = "",
  helperText,
  ...props
}) {
  return (
    <div className={`mb-4 ${className}`}>
      {label && (
        <label className="block mb-1.5 text-[11px] font-bold uppercase tracking-wider text-slate-300 font-sans">
          {label}
        </label>
      )}

      <div className="relative flex items-center">
        {Icon && (
          <div className="absolute left-3.5 text-slate-400 pointer-events-none transition-colors">
            <Icon className="w-4 h-4" />
          </div>
        )}

        <input
          type={type}
          placeholder={placeholder}
          {...register}
          {...props}
          className={`w-full bg-slate-800/90 text-white placeholder-slate-500 text-xs sm:text-sm font-medium rounded-xl border py-2.5 transition-all duration-200 shadow-sm outline-none ${Icon ? "pl-10 pr-4" : "px-4"
            } ${error
              ? "border-red-500/80 bg-red-500/10 focus:ring-2 focus:ring-red-500/20 focus:border-red-500 text-red-200"
              : "border-slate-700/80 focus:border-orange-500 focus:ring-2 focus:ring-orange-500/20 hover:border-slate-600"
            }`}
        />
      </div>

      {helperText && !error && (
        <p className="text-slate-400 text-xs mt-1.5">{helperText}</p>
      )}

      {error && (
        <p className="text-red-400 text-xs font-semibold mt-1.5 flex items-center gap-1">
          <span>•</span> {error.message}
        </p>
      )}
    </div>
  );
}

export default Input;

import React from "react";
import EduSphereLogo from "./EduSphereLogo";

function Loader({ fullScreen = false, text = "Loading EduSphere..." }) {
  const content = (
    <div className="flex flex-col items-center justify-center p-8 gap-4 select-none">
      <div className="relative">
        <EduSphereLogo size="lg" showText={false} />
        <div className="absolute -inset-2 rounded-2xl bg-gradient-to-r from-orange-600 to-emerald-800 blur-lg opacity-30 animate-pulse"></div>
      </div>
      <div className="flex items-center gap-2">
        <div className="w-2 h-2 rounded-full bg-orange-600 animate-bounce"></div>
        <div className="w-2 h-2 rounded-full bg-emerald-800 animate-bounce [animation-delay:0.2s]"></div>
        <div className="w-2 h-2 rounded-full bg-blue-600 animate-bounce [animation-delay:0.4s]"></div>
      </div>
      <p className="text-xs font-semibold tracking-wider text-slate-500 uppercase">{text}</p>
    </div>
  );

  if (fullScreen) {
    return (
      <div className="fixed inset-0 z-50 bg-[#05110d]/80 backdrop-blur-md flex items-center justify-center">
        {content}
      </div>
    );
  }

  return content;
}

export default Loader;

import React, { useState } from "react";
import { Eye, EyeOff, Lock } from "lucide-react";

function PasswordInput({
  label,
  placeholder,
  register,
  error,
  icon: Icon = Lock,
  className = "",
  ...props
}) {
  const [showPassword, setShowPassword] = useState(false);

  return (
    <div className={`mb-4 ${className}`}>
      {label && (
        <label className="block mb-1.5 text-[11px] font-bold uppercase tracking-wider text-slate-300 font-sans">
          {label}
        </label>
      )}

      <div className="relative flex items-center">
        {Icon && (
          <div className="absolute left-3.5 text-slate-400 pointer-events-none">
            <Icon className="w-4 h-4" />
          </div>
        )}

        <input
          type={showPassword ? "text" : "password"}
          placeholder={placeholder}
          {...register}
          {...props}
          className={`w-full bg-slate-800/90 text-white placeholder-slate-500 text-xs sm:text-sm font-medium rounded-xl border py-2.5 pr-11 transition-all duration-200 shadow-sm outline-none ${Icon ? "pl-10" : "px-4"
            } ${error
              ? "border-red-500/80 bg-red-500/10 focus:ring-2 focus:ring-red-500/20 focus:border-red-500 text-red-200"
              : "border-slate-700/80 focus:border-orange-500 focus:ring-2 focus:ring-orange-500/20 hover:border-slate-600"
            }`}
        />

        <button
          type="button"
          onClick={() => setShowPassword(!showPassword)}
          className="absolute right-3.5 text-slate-400 hover:text-slate-200 transition-colors p-1 rounded-lg focus:outline-none cursor-pointer"
        >
          {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
        </button>
      </div>

      {error && (
        <p className="text-red-400 text-xs font-semibold mt-1.5 flex items-center gap-1">
          <span>•</span> {error.message}
        </p>
      )}
    </div>
  );
}

export default PasswordInput;

