import toast from "react-hot-toast";
import { useConfirm } from "../../context/ConfirmContext";
import React, { useState, useEffect } from "react";
import Card from "../common/Card";
import Button from "../common/Button";
import api from "../../api/api";
import { BookOpen, Upload, Trash2, Eye, FileText, X, Users, CheckCircle2, Clock } from "lucide-react";

export default function TeacherNotesSection({ assignedBatches, uploadableBatches = [] }) {
  const confirm = useConfirm();
  const [notes, setNotes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [uploading, setUploading] = useState(false);

  // Upload form state
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [file, setFile] = useState(null);

  // Stats modal state
  const [statsNote, setStatsNote] = useState(null);
  const [studentStats, setStudentStats] = useState([]);
  const [loadingStats, setLoadingStats] = useState(false);

  const [selectedBatchId, setSelectedBatchId] = useState("");

  useEffect(() => {
    if (uploadableBatches?.length > 0 && !selectedBatchId) {
      setSelectedBatchId(uploadableBatches[0]);
    }
  }, [uploadableBatches, selectedBatchId]);

  const fetchNotes = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem("token");
      const res = await api.get("/notes/teacher", {
        headers: { Authorization: `Bearer ${token}` }
      });
      setNotes(res.data.notes || []);
    } catch (err) {
      console.error("Failed to fetch notes:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchNotes();
  }, []);

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files[0]) {
      const selectedFile = e.target.files[0];
      const validTypes = ["application/pdf", "application/msword", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "application/vnd.ms-powerpoint", "application/vnd.openxmlformats-officedocument.presentationml.presentation"];

      if (!validTypes.includes(selectedFile.type)) {
        toast.success("Please upload a valid PDF, DOC/DOCX, or PPT/PPTX file.");
        return;
      }

      if (selectedFile.size > 15 * 1024 * 1024) {
        toast.success("File size exceeds the 15MB limit.");
        return;
      }

      setFile(selectedFile);
    }
  };

  const handleUpload = async (e) => {
    e.preventDefault();
    if (!title || !file) {
      toast.error("Please provide a title and select a file.");
      return;
    }

    try {
      setUploading(true);
      const token = localStorage.getItem("token");
      const formData = new FormData();
      formData.append("title", title);
      formData.append("description", description);
      formData.append("file", file);

      if (selectedBatchId) {
        formData.append("batchId", selectedBatchId);
      }

      await api.post("/notes", formData, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data"
        }
      });

      toast.success("Note uploaded successfully!");
      setShowUploadModal(false);
      setTitle("");
      setDescription("");
      setFile(null);
      fetchNotes();
    } catch (err) {
      console.error(err);
      toast.error(err.response?.data?.message || "Failed to upload note.");
    } finally {
      setUploading(false);
    }
  };

  const handleDelete = async (noteId) => {
    const isConfirmed = await confirm({ title: "Delete Note", message: "Are you sure you want to delete this study material?", confirmText: "Delete", isDanger: true });
    if (!isConfirmed) return;

    try {
      const token = localStorage.getItem("token");
      await api.delete(`/notes/${noteId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fetchNotes();
    } catch (err) {
      toast.error("Failed to delete note.");
    }
  };

  const openStatsModal = async (note) => {
    setStatsNote(note);
    setLoadingStats(true);
    try {
      const token = localStorage.getItem("token");
      const res = await api.get(`/notes/${note._id}/views`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setStudentStats(res.data.stats || []);
    } catch (err) {
      toast.error("Failed to fetch student view statistics.");
      setStatsNote(null);
    } finally {
      setLoadingStats(false);
    }
  };

  if (uploadableBatches.length === 0) {
    return null;
  }

  return (
    <Card className="p-6 mt-8">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
        <div>
          <h3 className="text-lg font-bold text-[#0D2F24] flex items-center gap-2">
            <BookOpen className="w-5 h-5 text-orange-600" />
            Study Materials & Notes
          </h3>
          <p className="text-xs text-slate-500 mt-1">
            Upload study materials (PDF, DOC, PPT) for your assigned batches.
          </p>
        </div>

        {uploadableBatches.length > 0 && (
          <Button
            onClick={() => setShowUploadModal(true)}
            className="bg-orange-600 hover:bg-orange-700 text-white flex items-center gap-2 text-xs py-2 px-4"
          >
            <Upload className="w-4 h-4" /> Upload Material
          </Button>
        )}
      </div>

      {loading ? (
        <div className="py-8 text-center text-xs text-slate-400">Loading notes...</div>
      ) : notes.length === 0 ? (
        <div className="py-12 border-2 border-dashed border-slate-200 rounded-2xl text-center flex flex-col items-center">
          <FileText className="w-8 h-8 text-slate-300 mb-2" />
          <p className="text-sm font-bold text-slate-600">No materials available yet</p>
          <p className="text-xs text-slate-400 max-w-xs mt-1">
            {uploadableBatches.length > 0
              ? "You haven't uploaded any study materials for your assigned batches."
              : "Subject teachers haven't uploaded any study materials for your assigned batches yet."}
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {notes.map(note => (
            <div key={note._id} className="border border-slate-200 rounded-xl p-4 hover:border-orange-300 transition hover:shadow-sm bg-white flex flex-col h-full">
              <div className="flex justify-between items-start mb-2">
                <div className="w-10 h-10 rounded-lg bg-orange-50 flex items-center justify-center shrink-0">
                  <FileText className="w-5 h-5 text-orange-600" />
                </div>
                <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-slate-100 text-slate-600">
                  {note.batchId}
                </span>
              </div>

              <h4 className="font-bold text-[#0D2F24] mt-2 truncate" title={note.title}>{note.title}</h4>
              <p className="text-xs text-slate-500 line-clamp-2 mt-1 min-h-[32px]">{note.description || "No description"}</p>

              <div className="mt-4 pt-4 border-t border-slate-100 flex-grow flex flex-col justify-end">
                <div className="flex items-center justify-between text-xs mb-3">
                  <span className="text-slate-500 flex items-center gap-1">
                    <Eye className="w-3.5 h-3.5" /> {note.viewCount} / {note.totalStudents} Viewed
                  </span>
                  <span className="text-slate-400 font-mono">
                    {(note.fileSize / 1024 / 1024).toFixed(1)} MB
                  </span>
                </div>

                <div className="flex gap-2">
                  <button
                    onClick={() => openStatsModal(note)}
                    className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-700 py-1.5 rounded-lg text-[11px] font-bold transition flex items-center justify-center gap-1"
                  >
                    <Users className="w-3.5 h-3.5" /> View Stats
                  </button>
                  <button
                    onClick={() => handleDelete(note._id)}
                    className="w-8 flex items-center justify-center bg-rose-50 hover:bg-rose-100 text-rose-600 rounded-lg transition"
                    title="Delete Note"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* UPLOAD MODAL */}
      {showUploadModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#0D2F24]/60 backdrop-blur-sm animate-fadeIn">
          <div className="relative w-full max-w-md bg-white rounded-2xl p-6 shadow-2xl border border-slate-100">
            <button
              onClick={() => setShowUploadModal(false)}
              className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 p-1.5 rounded-full hover:bg-slate-100 transition"
            >
              <X className="w-5 h-5" />
            </button>

            <h3 className="font-bold text-[#0D2F24] text-lg mb-4 flex items-center gap-2">
              <Upload className="w-5 h-5 text-orange-600" /> Upload Study Material
            </h3>

            <form onSubmit={handleUpload} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">Title *</label>
                <input
                  type="text"
                  value={title}
                  onChange={e => setTitle(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-200 rounded-lg text-sm focus:outline-none focus:border-orange-500 transition"
                  placeholder="e.g. Newton's Laws - Chapter 1"
                  required
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">Description (Optional)</label>
                <textarea
                  value={description}
                  onChange={e => setDescription(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-200 rounded-lg text-sm focus:outline-none focus:border-orange-500 transition resize-none h-20"
                  placeholder="Brief context about this material..."
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">Target Batch *</label>
                <select
                  value={selectedBatchId}
                  onChange={e => setSelectedBatchId(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-200 rounded-lg text-sm focus:outline-none focus:border-orange-500 transition"
                  required
                >
                  {uploadableBatches.map(b => (
                    <option key={b} value={b}>{b}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">File * (PDF, DOCX, PPTX - Max 15MB)</label>
                <input
                  type="file"
                  onChange={handleFileChange}
                  accept=".pdf,.doc,.docx,.ppt,.pptx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation"
                  className="w-full text-xs text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-semibold file:bg-orange-50 file:text-orange-700 hover:file:bg-orange-100"
                  required
                />
              </div>

              <div className="pt-2">
                <Button
                  type="submit"
                  className="w-full py-2 bg-orange-600 hover:bg-orange-700 text-white"
                  disabled={uploading}
                >
                  {uploading ? "Uploading..." : "Upload Material"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* STATS MODAL */}
      {statsNote && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#0D2F24]/60 backdrop-blur-sm animate-fadeIn">
          <div className="relative w-full max-w-2xl bg-white rounded-2xl p-6 shadow-2xl border border-slate-100 flex flex-col max-h-[85vh]">
            <button
              onClick={() => setStatsNote(null)}
              className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 p-1.5 rounded-full hover:bg-slate-100 transition"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="mb-4 pr-8">
              <h3 className="font-bold text-[#0D2F24] text-lg line-clamp-1">{statsNote.title}</h3>
              <p className="text-xs font-semibold text-orange-600 mt-1">View Statistics &bull; {statsNote.batchId}</p>
            </div>

            <div className="flex gap-4 mb-4">
              <div className="flex-1 bg-emerald-50 border border-emerald-100 rounded-xl p-3">
                <span className="text-[10px] font-bold text-emerald-600 uppercase">Viewed By</span>
                <p className="text-xl font-black text-emerald-700 mt-1">
                  {studentStats.filter(s => s.hasViewed).length} <span className="text-xs font-medium text-emerald-600/70">/ {studentStats.length}</span>
                </p>
              </div>
              <div className="flex-1 bg-rose-50 border border-rose-100 rounded-xl p-3">
                <span className="text-[10px] font-bold text-rose-600 uppercase">Not Viewed</span>
                <p className="text-xl font-black text-rose-700 mt-1">
                  {studentStats.filter(s => !s.hasViewed).length}
                </p>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto pr-2 min-h-0">
              {loadingStats ? (
                <div className="py-8 text-center text-xs text-slate-400">Loading student statistics...</div>
              ) : (
                <div className="space-y-2">
                  {studentStats.map(student => (
                    <div key={student._id} className="flex items-center justify-between p-3 border border-slate-100 rounded-xl bg-slate-50 hover:bg-slate-100 transition">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-full bg-slate-200 text-slate-600 flex items-center justify-center text-xs font-bold shrink-0">
                          {student.fullName?.charAt(0)}
                        </div>
                        <div>
                          <p className="text-sm font-bold text-[#0D2F24] leading-tight">{student.fullName}</p>
                          <p className="text-[10px] font-mono text-slate-500">{student.admissionNumber}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        {student.hasViewed ? (
                          <>
                            <span className="inline-flex items-center gap-1 text-emerald-600 text-[11px] font-bold bg-emerald-100 px-2 py-0.5 rounded-full mb-1">
                              <CheckCircle2 className="w-3 h-3" /> Viewed
                            </span>
                            <p className="text-[9px] text-slate-400">
                              Last: {new Date(student.lastViewedAt).toLocaleDateString()}
                            </p>
                          </>
                        ) : (
                          <span className="inline-flex items-center gap-1 text-rose-500 text-[11px] font-bold bg-rose-100 px-2 py-0.5 rounded-full">
                            <Clock className="w-3 h-3" /> Pending
                          </span>
                        )}
                      </div>
                    </div>
                  ))}
                  {studentStats.length === 0 && (
                    <p className="text-center text-xs text-slate-400 py-4">No students found in this batch.</p>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </Card>
  );
}

import React, { createContext, useContext, useState, useEffect, useCallback } from "react";
import api from "../api/api";

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(() => {
    try {
      const savedUser = localStorage.getItem("user");
      return savedUser ? JSON.parse(savedUser) : null;
    } catch {
      return null;
    }
  });

  const [token, setToken] = useState(() => {
    return localStorage.getItem("token") || null;
  });

  const [isAuthenticated, setIsAuthenticated] = useState(() => {
    return Boolean(localStorage.getItem("token"));
  });

  const [loading, setLoading] = useState(true);

  // Helper to map role to dashboard path
  const getRoleDashboard = useCallback((roleInput) => {
    const roleUpper = (roleInput || "").toUpperCase();
    switch (roleUpper) {
      case "ADMINISTRATOR":
        return "/administrator/dashboard";
      case "ADMIN":
        return "/admin/dashboard";
      case "TEACHER":
        return "/teacher/dashboard";
      case "STUDENT":
        return "/student/dashboard";
      default:
        return "/dashboard";
    }
  }, []);

  // Restore/verify session from backend on app load
  const restoreSession = useCallback(async () => {
    const storedToken = localStorage.getItem("token");
    if (!storedToken) {
      setUser(null);
      setToken(null);
      setIsAuthenticated(false);
      setLoading(false);
      return;
    }

    try {
      // Validate token with backend /api/auth/me
      const response = await api.get("/auth/me");
      if (response.data && response.data.user) {
        setUser(response.data.user);
        setToken(storedToken);
        setIsAuthenticated(true);
        localStorage.setItem("user", JSON.stringify(response.data.user));
      } else {
        throw new Error("Invalid session response");
      }
    } catch (error) {
      console.warn("Session restoration failed:", error?.response?.data?.message || error.message);
      // Clear invalid session
      localStorage.removeItem("token");
      localStorage.removeItem("user");
      setUser(null);
      setToken(null);
      setIsAuthenticated(false);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    restoreSession();

    // Event listener for 401 unauthorized
    const handleUnauthorized = () => {
      setUser(null);
      setToken(null);
      setIsAuthenticated(false);
    };

    // Event listener for browser Back/Forward navigation (popstate)
    const handlePopState = () => {
      const currentToken = localStorage.getItem("token");
      if (!currentToken) {
        setUser(null);
        setToken(null);
        setIsAuthenticated(false);
      }
    };

    // Event listener for pages restored from browser back-forward cache (BFCache)
    const handlePageShow = (event) => {
      if (event.persisted) {
        restoreSession();
      }
    };

    window.addEventListener("auth:unauthorized", handleUnauthorized);
    window.addEventListener("popstate", handlePopState);
    window.addEventListener("pageshow", handlePageShow);

    return () => {
      window.removeEventListener("auth:unauthorized", handleUnauthorized);
      window.removeEventListener("popstate", handlePopState);
      window.removeEventListener("pageshow", handlePageShow);
    };
  }, [restoreSession]);

  // Centralized login method
  const login = (newToken, userData) => {
    localStorage.setItem("token", newToken);
    localStorage.setItem("user", JSON.stringify(userData));
    setToken(newToken);
    setUser(userData);
    setIsAuthenticated(true);
  };

  // Centralized logout method
  const logout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    setToken(null);
    setUser(null);
    setIsAuthenticated(false);
  };

  // Helper method to update local user state
  const updateUser = (updatedUserData) => {
    const mergedUser = { ...user, ...updatedUserData };
    localStorage.setItem("user", JSON.stringify(mergedUser));
    setUser(mergedUser);
  };

  const getUserRole = () => {
    return user?.role ? user.role.toUpperCase() : null;
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        isAuthenticated,
        loading,
        login,
        logout,
        restoreSession,
        updateUser,
        getUserRole,
        getRoleDashboard,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
};

export default AuthContext;

import React, { createContext, useContext, useState, useCallback } from 'react';
import { AlertTriangle, X } from 'lucide-react';


const ConfirmContext = createContext();

export const useConfirm = () => {
  return useContext(ConfirmContext);
};

export const ConfirmProvider = ({ children }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [options, setOptions] = useState({
    title: 'Confirm',
    message: 'Are you sure?',
    confirmText: 'Confirm',
    cancelText: 'Cancel',
    isDanger: false,
  });
  const [resolver, setResolver] = useState(null);

  const confirm = useCallback((opts) => {
    setOptions({
      title: opts.title || 'Confirm',
      message: opts.message || 'Are you sure?',
      confirmText: opts.confirmText || 'Confirm',
      cancelText: opts.cancelText || 'Cancel',
      isDanger: opts.isDanger || false,
    });
    setIsOpen(true);
    return new Promise((resolve) => {
      setResolver(() => resolve);
    });
  }, []);

  const handleConfirm = () => {
    setIsOpen(false);
    if (resolver) resolver(true);
  };

  const handleCancel = () => {
    setIsOpen(false);
    if (resolver) resolver(false);
  };

  return (
    <ConfirmContext.Provider value={confirm}>
      {children}
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-[#05110d]/60 backdrop-blur-sm animate-fadeIn">
          <div className="relative w-full max-w-sm bg-white dark:bg-[#0D2F24] rounded-2xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-800">
            <div className="p-6">
              <div className="flex items-center gap-4 mb-4">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center shrink-0 ${options.isDanger ? 'bg-red-100 text-red-600 dark:bg-red-500/20' : 'bg-amber-100 text-amber-600 dark:bg-amber-500/20'}`}>
                  <AlertTriangle className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="text-lg font-bold text-slate-800 dark:text-white">
                    {options.title}
                  </h3>
                </div>
              </div>
              <p className="text-sm text-slate-600 dark:text-slate-300">
                {options.message}
              </p>
            </div>
            <div className="px-6 py-4 bg-slate-50 dark:bg-[#05110d]/50 border-t border-slate-100 dark:border-slate-800 flex justify-end gap-3">
              <button
                onClick={handleCancel}
                className="px-4 py-2 rounded-xl text-sm font-semibold text-slate-600 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-800 transition"
              >
                {options.cancelText}
              </button>
              <button
                onClick={handleConfirm}
                className={`px-4 py-2 rounded-xl text-sm font-bold text-white transition shadow-lg ${
                  options.isDanger
                    ? 'bg-red-600 hover:bg-red-500 shadow-red-500/30'
                    : 'bg-orange-600 hover:bg-orange-500 shadow-orange-500/30'
                }`}
              >
                {options.confirmText}
              </button>
            </div>
          </div>
        </div>
      )}
    </ConfirmContext.Provider>
  );
};

import toast from "react-hot-toast";
import React, { useState, useEffect } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { MEDIA_URL } from "../api/api";
import EduSphereLogo from "../components/common/EduSphereLogo";
import {
  LayoutDashboard,
  Users,
  GraduationCap,
  UserCheck,
  ShieldCheck,
  Layers,
  CalendarCheck,
  Receipt,
  FileText,
  BarChart3,
  Settings,
  LogOut,
  Search,
  Bell,
  Sun,
  Moon,
  ChevronLeft,
  ChevronRight,
  ChevronDown,
  Menu,
  X,
  Sparkles,
  CheckCircle2,
  BookOpen,
  Key
} from "lucide-react";

function AdminLayout({ children, title }) {
  const location = useLocation();
  const navigate = useNavigate();
  const { user: authUser, logout } = useAuth();
  const user = authUser || JSON.parse(localStorage.getItem("user") || "{}");

  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showProfileMenu, setShowProfileMenu] = useState(false);

  // Toggle Dark Mode class on body/root element
  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }
  }, [darkMode]);

  // Determine Role-Based Navigation Items
  const getNavItems = () => {
    const roleUpper = (user.role || "").toUpperCase();

    if (roleUpper === "STUDENT") {
      return [
        { name: "My Dashboard", path: "/student/dashboard", icon: LayoutDashboard },
        { name: "My Quizzes", path: "/student/quizzes", icon: BookOpen },
        { name: "Attendance Record", path: "/student/attendance", icon: CalendarCheck },
        { name: "Leave Applications", path: "/student/leaves", icon: FileText },
        { name: "Exams & Results", path: "/student/results", icon: FileText },
        { name: "Fee Payments", path: "/student/fees", icon: Receipt },
        { name: "Change Password", path: "/change-password", icon: Key },
      ];
    }

    if (roleUpper === "TEACHER") {
      return [
        { name: "Faculty Dashboard", path: "/teacher/dashboard", icon: LayoutDashboard },
        { name: "Manage Subject Teachers", path: "/teacher/subject-teachers", icon: Users },
        { name: "Quiz Management", path: "/teacher/quizzes", icon: FileText },
        { name: "My Batches", path: "/teacher/batches", icon: Layers, isPlaceholder: true },
        { name: "Mark Attendance", path: "/teacher/attendance", icon: CalendarCheck },
        { name: "Leave Approvals", path: "/teacher/leaves", icon: FileText },
        { name: "Student Directory", path: "/administrator/students", icon: GraduationCap },
      ];
    }

    if (roleUpper === "ADMIN") {
      return [
        { name: "Admin Dashboard", path: "/admin/dashboard", icon: LayoutDashboard },
        { name: "Student Directory", path: "/administrator/students", icon: GraduationCap, badge: "View Only" },
        { name: "Batch Management", path: "/administrator/batches", icon: Layers },
        { name: "Attendance Records", path: "/administrator/attendance", icon: CalendarCheck, isPlaceholder: true },
        { name: "Timetable Allocation", path: "/admin/timetable", icon: CalendarCheck },
        { name: "Fee Management", path: "/admin/fees", icon: Receipt },
        { name: "Reports & Analytics", path: "/administrator/reports", icon: BarChart3 },
        { name: "Change Password", path: "/change-password", icon: Key },
      ];
    }

    // Default Administrator (Super Admin) Nav Items
    return [
      { name: "Dashboard", path: "/administrator/dashboard", icon: LayoutDashboard },
      { name: "Student Management", path: "/administrator/students", icon: GraduationCap, badge: "Live" },
      { name: "Teacher Management", path: "/administrator/teachers", icon: Users },
      { name: "Admin Management", path: "/administrator/admins", icon: ShieldCheck },
      { name: "Batch Management", path: "/administrator/batches", icon: Layers, badge: "View Only" },
      { name: "Timetable Allocation", path: "/administrator/timetable", icon: CalendarCheck },
      { name: "Attendance", path: "/administrator/attendance", icon: CalendarCheck, isPlaceholder: true },
      { name: "Fees", path: "/administrator/fees", icon: Receipt },
      { name: "Exams & Marks", path: "/administrator/exams", icon: FileText, isPlaceholder: true },
      { name: "Reports & Analytics", path: "/administrator/reports", icon: BarChart3 },
      { name: "Settings", path: "/administrator/settings", icon: Settings, isPlaceholder: true },
    ];
  };

  const navItems = getNavItems();

  const getDashboardHomePath = () => {
    const roleUpper = (user.role || "").toUpperCase();
    switch (roleUpper) {
      case "STUDENT":
        return "/student/dashboard";
      case "TEACHER":
        return "/teacher/dashboard";
      case "ADMIN":
        return "/admin/dashboard";
      default:
        return "/administrator/dashboard";
    }
  };

  const handleLogout = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    try {
      if (logout) {
        logout();
      } else {
        localStorage.removeItem("token");
        localStorage.removeItem("user");
      }
    } catch {
      localStorage.removeItem("token");
      localStorage.removeItem("user");
    }

    if (typeof window !== "undefined") {
      window.location.replace("/login");
    } else {
      navigate("/login", { replace: true });
    }
  };

  const notificationsList = [
    { id: 1, text: "System notification received", time: "10m ago", unread: true },
    { id: 2, text: "Academic calendar updated", time: "2h ago", unread: false },
  ];

  return (
    <div className={`min-h-screen font-sans ${darkMode ? "bg-[#05110d] text-[#FDFBF7]" : "bg-[#FDFBF7] text-[#0D2F24]"} flex overflow-hidden`}>
      {/* MOBILE OVERLAY */}
      {mobileOpen && (
        <div
          onClick={() => setMobileOpen(false)}
          className="fixed inset-0 bg-[#0D2F24]/60 backdrop-blur-sm z-40 lg:hidden"
        />
      )}

      {/* LEFT SIDEBAR */}
      <aside
        className={`fixed lg:static inset-y-0 left-0 z-50 flex flex-col bg-[#0D2F24] text-white transition-all duration-300 ease-in-out border-r border-white/5 ${collapsed ? "w-20" : "w-72"
          } ${mobileOpen ? "translate-x-0" : "-translate-x-full lg:translate-x-0"}`}
      >
        {/* LOGO AREA */}
        <div className="h-20 px-5 flex items-center justify-between border-b border-white/5">
          <Link to={getDashboardHomePath()} className="flex items-center">
            {collapsed ? (
              <EduSphereLogo size="sm" showText={false} light={true} />
            ) : (
              <EduSphereLogo size="md" showText={true} showSubtitle={false} light={true} />
            )}
          </Link>

          {/* Desktop Collapse Toggle */}
          <button
            onClick={() => setCollapsed(!collapsed)}
            className="hidden lg:flex p-1.5 rounded-lg bg-white/5 text-white/50 hover:text-white hover:bg-white/10 transition"
            title={collapsed ? "Expand Sidebar" : "Collapse Sidebar"}
          >
            {collapsed ? <ChevronRight className="w-4 h-4" /> : <ChevronLeft className="w-4 h-4" />}
          </button>

          {/* Mobile Close Button */}
          <button
            onClick={() => setMobileOpen(false)}
            className="lg:hidden p-1.5 text-slate-400 hover:text-white"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* NAVIGATION LINKS */}
        <div className="flex-1 overflow-y-auto py-4 px-3 space-y-1">
          <div className={`px-3 mb-2 text-[10px] font-bold uppercase tracking-wider text-[#A3B3AA] ${collapsed ? "hidden" : "block"}`}>
            {user.role ? `${user.role} Menu` : "Main Menu"}
          </div>

          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = location.pathname === item.path;

            return (
              <Link
                key={item.name}
                to={item.isPlaceholder ? "#" : item.path}
                onClick={(e) => {
                  if (item.isPlaceholder) {
                    e.preventDefault();
                    toast.success(`${item.name} module is active under your ${user.role || 'user'} portal.`);
                  } else {
                    setMobileOpen(false);
                  }
                }}
                className={`group relative flex items-center gap-3.5 px-3.5 py-3 rounded-xl text-sm font-semibold transition-all duration-200 ${isActive
                  ? "bg-gradient-to-r from-[#D9531E] to-[#C94921] text-white shadow-lg shadow-[#D9531E]/20"
                  : "text-[#8B9E95] hover:bg-white/5 hover:text-white"
                  } ${collapsed ? "justify-center px-0" : ""}`}
                title={collapsed ? item.name : undefined}
              >
                <Icon className={`w-5 h-5 shrink-0 ${isActive ? "text-white" : "text-[#8B9E95] group-hover:text-[#E25C31]"}`} />

                {!collapsed && (
                  <span className="truncate flex-1 flex items-center justify-between">
                    {item.name}
                    {item.badge && (
                      <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-white/10 border border-white/20 text-[#FDFBF7]">
                        {item.badge}
                      </span>
                    )}
                  </span>
                )}

                {/* Active Indicator Glow */}
                {isActive && !collapsed && (
                  <span className="w-1.5 h-6 rounded-r-full bg-white absolute left-0 top-1/2 -translate-y-1/2" />
                )}
              </Link>
            );
          })}
        </div>

        {/* FOOTER USER / LOGOUT AREA */}
        <div className="p-4 border-t border-white/5 bg-black/10">
          <button
            onClick={handleLogout}
            className={`w-full flex items-center gap-3 px-3.5 py-3 rounded-xl text-sm font-semibold text-red-400 hover:bg-red-500/10 hover:text-red-300 transition ${collapsed ? "justify-center" : ""
              }`}
            title="Logout"
          >
            <LogOut className="w-5 h-5 shrink-0" />
            {!collapsed && <span>Sign Out</span>}
          </button>
        </div>
      </aside>

      {/* MAIN CONTENT CONTAINER */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* TOP NAVBAR */}
        <header className={`h-20 px-6 sm:px-8 border-b ${darkMode ? "bg-[#0D2F24] border-white/5 text-white" : "bg-[#FDFBF7] border-[#E8E2D2] text-[#0D2F24]"} flex items-center justify-between sticky top-0 z-30 shadow-xs`}>
          {/* Left: Mobile Menu Toggle & Title */}
          <div className="flex items-center gap-4">
            <button
              onClick={() => setMobileOpen(true)}
              className={`lg:hidden p-2 rounded-xl transition ${darkMode ? "text-[#A3B3AA] hover:text-white hover:bg-white/5" : "text-[#8B9E95] hover:text-[#0D2F24] hover:bg-white"}`}
            >
              <Menu className="w-6 h-6" />
            </button>

            <div>
              <h1 className="text-xl font-extrabold tracking-tight">{title}</h1>
              <p className={`text-xs font-semibold ${darkMode ? "text-[#A3B3AA]" : "text-[#65776F]"} hidden sm:block`}>EduSphere Platform Workspace</p>
            </div>
          </div>

          {/* Center: Search Bar */}
          <div className="hidden md:flex items-center relative w-72 lg:w-96">
            <Search className="w-4 h-4 absolute left-3.5 text-[#8B9E95]" />
            <input
              type="text"
              placeholder="Search courses, announcements, records (Ctrl + K)..."
              className={`w-full pl-10 pr-12 py-2.5 rounded-xl text-xs font-semibold border ${darkMode
                ? "bg-[#05110d] border-white/10 text-white placeholder-[#8B9E95] focus:border-[#D9531E]"
                : "bg-white border-[#E8E2D2] text-[#0D2F24] placeholder-[#A3B3AA] focus:border-[#D9531E] focus:ring-1 focus:ring-[#D9531E]"
                } outline-none transition shadow-sm`}
            />
            <span className={`absolute right-3 text-[10px] font-bold px-1.5 py-0.5 rounded ${darkMode ? "bg-white/10 text-[#A3B3AA]" : "bg-[#FDFBF7] border border-[#E8E2D2] text-[#65776F]"}`}>
              ⌘K
            </span>
          </div>

          {/* Right: Controls & Profile */}
          <div className="flex items-center gap-3">
            {/* Dark Mode Toggle */}
            <button
              onClick={() => setDarkMode(!darkMode)}
              className={`p-2.5 rounded-xl border transition shadow-sm ${darkMode
                ? "bg-[#05110d] border-white/10 text-amber-400 hover:bg-white/5"
                : "bg-white border-[#E8E2D2] text-[#65776F] hover:bg-[#FDFBF7] hover:text-[#D9531E]"
                }`}
              title="Toggle Dark / Light Theme"
            >
              {darkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
            </button>

            {/* Notifications Dropdown Toggle */}
            <div className="relative">
              <button
                onClick={() => {
                  setShowNotifications(!showNotifications);
                  setShowProfileMenu(false);
                }}
                className={`relative p-2.5 rounded-xl border transition shadow-sm ${darkMode
                  ? "bg-[#05110d] border-white/10 text-[#A3B3AA] hover:bg-white/5"
                  : "bg-white border-[#E8E2D2] text-[#65776F] hover:bg-[#FDFBF7] hover:text-[#D9531E]"
                  }`}
              >
                <Bell className="w-4 h-4" />
                <span className="absolute top-2 right-2 w-2 h-2 rounded-full bg-[#D9531E] ring-2 ring-white"></span>
              </button>

              {showNotifications && (
                <div className={`absolute right-0 mt-3 w-80 rounded-2xl border shadow-2xl p-4 z-50 ${darkMode ? "bg-[#0D2F24] border-white/10 text-white shadow-black/50" : "bg-white border-[#E8E2D2] text-[#0D2F24] shadow-black/10"
                  }`}>
                  <div className="flex items-center justify-between pb-3 mb-3 border-b border-gray-200/20">
                    <h4 className="font-bold text-xs uppercase tracking-wider">Notifications</h4>
                    <span className="text-[10px] font-bold text-white bg-[#D9531E] px-2 py-0.5 rounded-full">2 New</span>
                  </div>
                  <div className="space-y-2">
                    {notificationsList.map((n) => (
                      <div key={n.id} className={`p-2.5 rounded-xl transition cursor-pointer text-xs ${darkMode ? "bg-[#05110d] hover:bg-white/5" : "bg-[#FDFBF7] hover:bg-[#F2EDDF]"}`}>
                        <p className={`font-semibold ${darkMode ? "text-white" : "text-[#0D2F24]"}`}>{n.text}</p>
                        <span className={`text-[10px] ${darkMode ? "text-[#A3B3AA]" : "text-[#65776F]"}`}>{n.time}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Profile Dropdown */}
            <div className="relative">
              <button
                onClick={() => {
                  setShowProfileMenu(!showProfileMenu);
                  setShowNotifications(false);
                }}
                className={`flex items-center gap-3 p-1.5 rounded-xl transition ${darkMode ? "hover:bg-white/5" : "hover:bg-white border border-transparent hover:border-[#E8E2D2]"}`}
              >
                <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-[#D9531E] to-[#C94921] text-white flex items-center justify-center font-extrabold text-sm shadow-md overflow-hidden">
                  {user.profilePic ? (
                    <img
                      src={user.profilePic.startsWith("http") ? user.profilePic : `${MEDIA_URL}${user.profilePic}`}
                      alt={user.name || "User"}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    user.name ? user.name.charAt(0).toUpperCase() : "U"
                  )}
                </div>
                <div className="text-left hidden sm:block">
                  <p className="text-xs font-bold leading-tight">{user.name || "User"}</p>
                  <p className={`text-[10px] font-bold ${darkMode ? "text-[#E25C31]" : "text-[#D9531E]"}`}>{user.role || "Student"}</p>
                </div>
                <ChevronDown className={`w-4 h-4 hidden sm:block ${darkMode ? "text-[#8B9E95]" : "text-[#A3B3AA]"}`} />
              </button>

              {showProfileMenu && (
                <div className={`absolute right-0 mt-3 w-56 rounded-2xl border shadow-2xl p-2 z-50 ${darkMode ? "bg-[#0D2F24] border-white/10 text-white shadow-black/50" : "bg-white border-[#E8E2D2] text-[#0D2F24] shadow-black/10"
                  }`}>
                  <div className="px-3 py-2 border-b border-gray-200/20 mb-1">
                    <p className="text-xs font-bold">{user.name}</p>
                    <p className={`text-[11px] truncate font-semibold ${darkMode ? "text-[#A3B3AA]" : "text-[#65776F]"}`}>{user.email}</p>
                  </div>

                  <Link
                    to="/change-password"
                    onClick={() => setShowProfileMenu(false)}
                    className={`flex items-center gap-2 px-3 py-2.5 text-xs font-bold rounded-xl transition ${darkMode ? "text-white hover:bg-white/5" : "text-[#0D2F24] hover:bg-[#FDFBF7] hover:text-[#D9531E]"}`}
                  >
                    <Key className="w-4 h-4" /> Change Password
                  </Link>

                  <button
                    onClick={handleLogout}
                    className={`w-full flex items-center gap-2 px-3 py-2.5 text-xs font-bold rounded-xl transition ${darkMode ? "text-red-400 hover:bg-red-500/10 hover:text-red-300" : "text-red-500 hover:bg-red-50"}`}
                  >
                    <LogOut className="w-4 h-4" />
                    Sign Out
                  </button>
                </div>
              )}
            </div>
          </div>
        </header>

        {/* DYNAMIC MAIN PAGE CONTENT */}
        <main className={`flex-1 overflow-y-auto p-6 sm:p-8 ${darkMode ? "bg-[#05110d]" : "bg-[#F9F6F0]"}`}>
          <div className="max-w-7xl mx-auto space-y-8">
            {children}
          </div>
        </main>
      </div>
    </div>
  );
}

export default AdminLayout;

