            <UserCheck className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-[#0D2F24]">Welcome, {user.name || "User"}</h2>
            <p className="text-xs text-slate-500">{user.email}</p>
          </div>
        </div>

        <div className="p-4 rounded-xl bg-slate-50 border border-slate-200/80 space-y-2 text-xs mb-6">
          <p><strong>Account Role:</strong> <span className="text-orange-600 font-bold">{user.role || "User"}</span></p>
          <p><strong>Platform Status:</strong> <span className="text-emerald-600 font-bold">Active</span></p>
        </div>

        <Button
          variant="danger"
          size="md"
          onClick={() => {
            localStorage.removeItem("token");
            localStorage.removeItem("user");
            window.location.href = "/login";
          }}
        >
          Sign Out
        </Button>
      </Card>
    </AdminLayout>
  );
}

export default Dashboard;

